# This code was generated using Anthropic Claude Code Opus 5.5

import os
import re
import sys
from collections import deque


def fail(msg):
    sys.stderr.write('genOrdering: ' + msg + '\n')
    sys.exit(1)


#
# Attack Graphs
#

# One attack graph from a file generated by xhtml2coq.py, given
# labels: adversary event => (cor|rep, component)
#   pi:     adversary events on some edge, in order of first appearance
#   tagged: event in pi => (tau|blank, cor|rep, component), tau if a measurement precedes it
class Graph:

    def __init__(self, qualname, edges, labels):
        self.qualname = qualname
        self.pi = []
        for e1, e2 in edges:
            for ev in (e1, e2):
                if ev in labels and ev not in self.pi:
                    self.pi.append(ev)
        tau = set(e2 for e1, e2 in edges if e1 not in labels and e2 in labels)
        self.tagged = {ev: ('tau' if ev in tau else 'blank',) + labels[ev] for ev in self.pi}


# Definition X : attackgraph components := {| ... |}.
GRAPH_RE = re.compile(r'Definition\s+(\w+)\s*:\s*attackgraph\s+components\s*:=\s*\{\|(.*?)\|\}\s*\.', re.S)
# (4,0)
EDGE_RE = re.compile(r'\(\s*(\d+)\s*,\s*(\d+)\s*\)')
# | 4 => inr (cor _ ima)
ADV_ARM_RE = re.compile(r'\|\s*(\d+)\s*=>\s*inr\s*\(\s*(cor|rep)\s+_\s+(\w+)\s*\)')


# The graphs of the list Definition module : list (attackgraph components) := A0 :: A1 :: nil,
# in list order, which proofs refer to by position
def load_protocol(path, module):
    with open(path) as f:
        text = f.read() + '\n'
    graphs = {}
    for m in GRAPH_RE.finditer(text):
        name, body = m.group(1), m.group(2)
        em = re.search(r'edges\s*:=(.*?);', body, re.S)
        if not em:
            fail('cannot parse attack graph %s in %s' % (name, path))
        edges = [(int(a), int(b)) for a, b in EDGE_RE.findall(em.group(1))]
        labels = {int(ev): (kind, comp) for ev, kind, comp in ADV_ARM_RE.findall(body)}
        graphs[name] = Graph('%s.%s' % (module, name), edges, labels)
    m = re.search(r'Definition\s+%s\s*:\s*list\s*\(\s*attackgraph\s+components\s*\)\s*:=(.*?)\.\s'
                  % re.escape(module), text, re.S)
    if not m:
        fail('no Definition %s : list (attackgraph components) in %s' % (module, path))
    return [graphs[n] for n in re.split(r'\s*::\s*', m.group(1).strip()) if n != 'nil']


class Protocols:

    def __init__(self, exdir):
        self.exdir = exdir
        self.loaded = {}        # protocol name => list of Graphs

    # ('P6', 'P7') => graphs of P6 ++ P7
    def graphs(self, P):
        out = []
        for name in P:
            if name not in self.loaded:
                path = os.path.join(self.exdir, name + '.v')
                if not os.path.isfile(path):
                    fail('no attack graphs %s' % path)
                self.loaded[name] = load_protocol(path, name)
            out += self.loaded[name]
        return out


#
# Adversary Orderings
#

# tauTag _ (cor _ ima)
TAGGED_RE = r'(tauTag|blankTag)\s+_\s+\(\s*(cor|rep)\s+_\s+(\w+)\s*\)'
# (tauTag _ (cor _ ima), blankTag _ (cor _ vmi))
PAIR_RE = re.compile(r'\(\s*' + TAGGED_RE + r'\s*,\s*' + TAGGED_RE + r'\s*\)')


def read_adv_ordering(exdir):
    adv = os.path.join(exdir, 'advOrder.v')
    if not os.path.isfile(adv):
        fail('no advOrder.v in %s' % exdir)
    with open(adv) as f:
        return f.read()


# makeTrianglelefteq name: the reflexive-transitive closure of the pairs of the
# list name in advOrder.v and blank(l) <= tau(l), with the Coq terms proofs use for it
class Ordering:

    def __init__(self, text, name):
        self.name = name
        self.succ = {}          # t1 => [t2 for each pair (t1, t2)]
        for t1, t2 in self.read_pairs(text, name):
            self.succ.setdefault(t1, []).append(t2)
        # Lemma NAME : forall x y, makeTrianglelefteq name x y -> makeTrianglelefteq name y x -> x = y.
        m = re.search(r'(?:Lemma|Theorem)\s+([\w\']+)\s*:\s*forall\s+(\w+)\s+(\w+)\s*,'
                      r'\s*makeTrianglelefteq\s+{0}\s+\2\s+\3\s*->\s*makeTrianglelefteq\s+{0}\s+\3\s+\2\s*->'
                      r'\s*\2\s*=\s*\3\s*\.'.format(re.escape(name)), text)
        if not m:
            fail('advOrder.v proves no lemma that makeTrianglelefteq %s is antisymmetric' % name)
        self.rel = '(makeTrianglelefteq %s)' % name
        self.dec = '(makeTrianglelefteqDec eqDec_components %s)' % name
        self.refl = '(makeTrianglelefteq_reflexive %s)' % name
        self.antisym = m.group(1)
        self.trans = '(makeTrianglelefteq_transitive %s)' % name

    # The pairs of the list name, which ends in nil or another list
    @staticmethod
    def read_pairs(text, name):
        m = re.search(r'Definition\s+%s\s*:[^=]*:=(.*?)\.\s' % re.escape(name), text, re.S)
        if not m:
            fail('no adversary ordering %s in advOrder.v' % name)
        pairs = [(('tau' if g[0] == 'tauTag' else 'blank', g[1], g[2]),
                  ('tau' if g[3] == 'tauTag' else 'blank', g[4], g[5])) for g in PAIR_RE.findall(m.group(1))]
        rest = PAIR_RE.sub('', m.group(1)).replace('::', ' ').split()
        if rest == ['nil']:
            return pairs
        if len(rest) == 1 and rest[0] != name:
            return pairs + Ordering.read_pairs(text, rest[0])
        fail('cannot read %s (expected literal pairs ending in nil or another list)' % name)

    # Breadth-first search from t1
    def le(self, t1, t2):
        seen = {t1}
        todo = deque([t1])
        while todo:
            t = todo.popleft()
            for u in self.succ.get(t, []) + ([('tau',) + t[1:]] if t[0] == 'blank' else []):
                if u not in seen:
                    seen.add(u)
                    todo.append(u)
        return t2 in seen


#
# Spec Files
#
# Each line of myOrdering.spec is one of
#   NAME := SIDE                an alias for SIDE
#   [NAME :] ORDER LHS RHS      a verdict lemma NAME (default ORDER_LHS_vs_RHS)
# where '#' starts a comment. A side is P1, P9t1++P9t2, {T123,T132}, or an alias.
#

IDENT = r"[A-Za-z_][\w']*"


# ('alias', name, side) or ('pair', name or None, order, lhs, rhs) for each line
def read_spec(spec):
    items = []
    with open(spec) as f:
        for line in f:
            line = line.split('#', 1)[0].strip()
            if line:
                items.append(parse_item(line, spec))
    return items


def parse_item(line, spec):
    m = re.fullmatch(r'(%s)\s*:=\s*(.+)' % IDENT, line)
    if m:
        return ('alias', m.group(1), m.group(2).strip())
    name = None
    m = re.fullmatch(r'(%s)\s*:(?!=)\s*(.+)' % IDENT, line)
    if m:
        name, line = m.group(1), m.group(2)
    words = re.findall(r'\{[^}]*\}|\S+', line)
    if len(words) != 3:
        fail('%s: expected "[NAME :] ORDER LHS RHS" or "NAME := SIDE", got %r' % (spec, line))
    return ('pair', name) + tuple(words)


# kind:  'set' or 'trace'
# value: aliases expanded, ('P9t1', 'P9t2') for a set or (('T123',), ('T132',)) for traces
# coq:   as written, as a Coq term
# ident: as written, as part of a lemma name
class Side:

    def __init__(self, kind, value, coq, ident):
        self.kind, self.value, self.coq, self.ident = kind, value, coq, ident

    def arg(self):
        return '(%s)' % self.coq if ' ' in self.coq else self.coq


class Sides:

    def __init__(self):
        self.aliases = {}       # name => Side

    def define(self, name, text):
        self.aliases[name] = side = self.parse(text)
        return side

    def parse_set(self, text):
        names = [n.strip() for n in text.split('++')]
        value = ()
        for n in names:
            if not re.fullmatch(IDENT, n):
                fail('cannot read %r' % text)
            alias = self.aliases.get(n)
            if alias is None:
                value += (n,)
            elif alias.kind == 'set':
                value += alias.value
            else:
                fail('%s is a list of traces, not a protocol, in %r' % (n, text))
        return Side('set', value, ' ++ '.join(names), '_app_'.join(names))

    def parse(self, text):
        text = text.strip()
        if text.startswith('{') and text.endswith('}'):
            sets = [self.parse_set(s) for s in text[1:-1].split(',')]
            return Side('trace', tuple(P.value for P in sets),
                        ' :: '.join([P.arg() for P in sets] + ['nil']),
                        '_'.join(P.ident for P in sets))
        alias = self.aliases.get(text)
        if alias is not None and alias.kind == 'trace':
            return Side('trace', alias.value, text, text)
        return self.parse_set(text)

    def parse_pair(self, lhs, rhs):
        L, R = self.parse(lhs), self.parse(rhs)
        if L.kind != R.kind:
            fail('%s and %s must be both protocols or both lists of traces' % (lhs, rhs))
        return L, R
